"""
    >>> merge_and_count_split_inv([1, 3, 5], [2, 4, 6])
    ([1, 2, 3, 4, 5, 6], 3)

    >>> merge_and_count_split_inv([1, 3, 5], [2, 4, 6, 7])
    ([1, 2, 3, 4, 5, 6, 7], 3)

    >>> merge_and_count_split_inv([1, 3, 5, 6], [2, 4, 7])
    ([1, 2, 3, 4, 5, 6, 7], 5)

    >>> merge_and_count_split_inv([1], [2])
    ([1, 2], 0)

    >>> merge_and_count_split_inv([2], [1])
    ([1, 2], 1)

    :param B:
    :param C:
    :return:
    """
def merge_and_count_split_inv(B: Any, C: Any) -> object {
    merged = [];
    inv_counter = 0;
    item_b = None;
    item_c = None;
    while (B or C or item_b or item_c) {
        if (not item_b and B) {
            item_b = B.pop(0);
        }
        if (not item_c and C) {
            item_c = C.pop(0);
        }
        if (item_b and item_c) {
            if (item_b <= item_c) {
                merged.append(item_b);
                item_b = None;
            } else {
                merged.append(item_c);
                if item_b {
                    inv_counter += 1 + len(B);
                }
                item_c = None;
            }
        } else {
            if item_b {
                merged.append(item_b);
                item_b = None;
            }
            if item_c {
                merged.append(item_c);
                item_c = None;
            }
        }
    }
    return (merged, inv_counter);
}

