"""
    Return the number of bytes n in more human readable form.

    Examples:
        >>> human_bytes(42)
        '42 B'
        >>> human_bytes(1042)
        '1 KB'
        >>> human_bytes(10004242)
        '9.5 MB'
        >>> human_bytes(100000004242)
        '93.13 GB'
    """
def human_bytes(n: Any) -> object {
    if (n < 1024) {
        return ('%d B' % n);
    }
    k = n / 1024;
    if (k < 1024) {
        return ('%d KB' % round(k));
    }
    m = k / 1024;
    if (m < 1024) {
        return ('%.1f MB' % m);
    }
    g = m / 1024;
    return ('%.2f GB' % g);
}
